INSERT INTO `sbm_indicator` (`id`, `indicator`, `description`) VALUES
(1, 'Curriculum and Teaching', 'School personnel and stakeholders work collaboratively to enhance learning standards to continually build a relevant and inclusive learning community and achieve improved learning outcomes.'),
(2, 'Learning Environment', 'The school and its community work collaboratively to ensure equitable access to a learner-centered, motivating, healthy, safe, secure, inclusive, resilient, and enabling learning environment and to achieve improved learning outcomes.'),
(3, 'Leadership', 'School personnel and stakeholders are empowered and actively engaged in taking on appropriate leadership roles and responsibilities to continuously improve the school for improved learning outcomes.'),
(4, 'Governance and Accountability', 'The school and its community come together to take responsibility for ensuring participation, transparency, and accountability, as well as the implementation of a plan to continuously improve the delivery of basic education services, organizational health, and performance for improved learning outcomes.'),
(5, 'Human Resource and Team Development', 'School personnel collaborate to continuously improve individual capabilities and team capacity to create an environment that shall yield high performance for improved learning outcomes.'),
(6, 'Finance and Resource Management and Mobilization', 'The school judiciously manages and mobilizes resources to support programs, projects, and activities the contribute to the improvement of learning outcomes.');
