INSERT INTO `sgod_action_plan` (`id`, `activity`, `objective`, `ex_output`, `metho_strategy`, `time_frame`, `person_involved`, `bud_req`, `remarks`, `fy`, `school_id`, `division`, `region`, `district`) VALUES
(1345, 'Enhancement of the Computer Laboratory', 'Provide a safe, organized, and learner-friendly computer laboratory environment\r\nIncrease the utilization of the computer laboratory in teaching and learning across subject areas\r\nEnhance learners’ digital literacy, ICT skills, and technological comp', 'Fully functional and improved computer laboratory/classroom with adequate ICT equipment\r\nIncreased number of operational computer units available for learner use\r\nStable and improved internet connectivity supporting ICT-based instruction\r\nEnhanced ICT integration in teaching and learning across subject areas\r\n', 'Needs Assessment and Planning\r\nConduct inventory and assessment of ICT equipment, connectivity, and learner needs as basis for upgrading the computer laboratory.\r\nResource Mobilization and Partnership Building\r\nEngage LGUs, PTA, alumni, and private partners for support in upgrading computers, internet access, and ICT facilities.\r\nRepair, Upgrade, and Maintenance Program\r\nImplement regular checking, repair, and upgrading of computer units, software, and laboratory equipment.\r\nICT Integration in Instruction\r\nPromote the use of the computer laboratory in teaching and learning activities across all subject areas.\r\nCapacity Building for Teachers\r\nConduct training on ICT integration, digital tools, and innovative teaching strategies.\r\nScheduled Laboratory Utilization\r\nDevelop and implement a fair and systematic schedule for computer laboratory use among learners and teachers.\r\nPreventive Maintenance System\r\nEstablish a routine maintenance plan to ensure functionality and longevity of ICT resources.\r\nSecurity and Inventory Management\r\nImplement proper tracking, labeling, and monitoring of all ICT equipment to prevent loss or damage.\r\nMonitoring and Evaluation\r\nRegularly assess the usage, condition, and effectiveness of the computer laboratory through reports and feedback.\r\nDigital Learning Support\r\nIntegrate online resources, educational software, and interactive platforms to enhance learner engagement.', 'School Year 2026-2027', 'Teacher / School Head', '50000.00', '           The enhancement of the computer laboratory/classroom is in progress to support ICT-integrated teaching and learning and improve learners’ digital literacy. Initial efforts on equipment maintenance, scheduling, and ICT integration have been implemented; however, further improvement is needed in upgrading computer units, strengthening internet connectivity, and expanding teacher capacity in ICT-based instruction. Continued support from stakeholders and sustained monitoring are essential to fully maximize the use of the computer laboratory for improved learner outcomes.', 2026, 128857, 59, 12, 139),
(1346, 'Reading Enhancement Program', 'Improve reading comprehension and fluency of learners', 'Increased reading levels and improve academic performance', 'Daily reading sessions; use of story books; remedial reading for struggling pupils', 'Whole school year ', 'Teachers, reading coordinators, pupils', '1000', 'Priority given to non-readers and slow readers', 2026, 205022, 59, 12, 147),
(1347, 'Conduct review classes and mock NAT exams', 'Increase NAT performance and mastery of competencies', 'Improved NAT scores', 'Review least mastered competencies', 'Quarterly', 'School Head and Competent Teachers', '3,00', 'Learners consistently meet proficiency standards; sustain best practices and document for benchmarking.', 2026, 304241, 58, 12, 38),
(1348, 'F5. Establishment of Confidential Reporting, Referral, and Response Mechanisms', 'Provide accessible, safe, and confidential systems for reporting suspected child abuse and ensure timely, appropriate, and child-sensitive response and intervention', 'Functional reporting and referral system with timely response to child abuse concerns', 'Reporting channels (suggestion boxes, hotlines); designate focal persons; ensure confidentiality; follow proper reporting and referral procedures; coordinate with authorities and child protection agencies', 'July 2026', 'School Head, CPC, Guidance Coordinator', '300', '', 2026, 304224, 58, 12, 36),
