INSERT INTO `sgod_action_plan` (`id`, `activity`, `objective`, `ex_output`, `metho_strategy`, `time_frame`, `person_involved`, `bud_req`, `remarks`, `fy`, `school_id`, `division`, `region`, `district`) VALUES
(1843, 'Capacity Building on School-Based Management (SBM) and Governance', 'Strengthen understanding of participatory governance.', 'Improved governance knowledge and participation', 'Training and workshops on SBM practices and leadership roles.', 'August 2026', 'School Head, DepEd Resource Persons, SGC Memb', '2500', '', 2026, 128649, 58, 12, 36),
(1844, 'Intensive Remedial and Enrichment Program for Learners\r\nNAT Simulation and Practice Testing', 'Provide targeted academic support to learners who scored below 50% in NAT practice tests and key competencies.\r\nFamiliarize learners with the NAT format, time pressure, and reduce test anxiety.', '- Monthly NAT mock tests (at least 3 simulations)\r\n- Analysis of mock test results\r\n- Individual learner feedback slips', '- Identify struggling learners using 1st quarter grades + baseline diagnostic test\r\n- Conduct 1-hour after-class remedial sessions (twice per week per subject)\r\n- Use small group tutoring, worksheets, and gamified drills\r\n- Monitor progress every 2 weeks\r\n- Prepare parallel tests based on previous NAT TOS\r\n- Simulate actual testing conditions (strict time, separate seats, answer sheets)\r\n- After each mock test, conduct an item discussion session focusing on common errors', 'Whole year', 'Testing Coordinator, Subject Teachers, Class ', '5000', 'Group learners by similar mastery level, not just by grade. Integrate with existing Homeroom PTA for volunteer support.\r\nDo not overdo simulations; one per month is enough. Use the results to adjust remedial focus.', 2026, 128950, 59, 12, 145),
(1845, 'Joint School Monitoring and Evaluation Activities', 'Strengthen transparency and shared accountability.', 'Improved transparency and decision-making', 'Conduct school visits, classroom observations, and program reviews with SGC ', 'Quarterly', 'School Head, SGC Members, Teachers', '1500', '', 2026, 128649, 58, 12, 36),
(1846, 'Implementation of Priority Projects', 'To address identified school needs', 'Completed priority projects', 'Resource Mobilization, coordination with LGU and donors', 'June 2026 - March 2027', 'School Head, SBM Coordinator, Teachers, PTA', '', 'Depends on fund availability.', 2026, 128673, 58, 12, 0),
(1847, 'Continuous Improvement (CI) Project', 'Address specific learning gaps identified in the School Improvement Plan', 'Documented CI Project report and improved  learner performance', 'Data analysis and implementation of localized interventions', 'June 2026 - March 2027', 'CI Team, Subject Area Coordinator', '1500.00', 'To be accomplished.', 2026, 128751, 58, 12, 41),
(1848, 'Stakeholder Engagement and Community  Participation Activities', 'Increase visibility and involvement of SGC in school programs.', 'Active stakeholder participation in school programs', 'Participation in Brigada Eskwela, PTA assemblies, and school events.', 'Throughout the School Year', 'SGC Members, PTA, Barangay Officials, Teacher', '2000', '', 2026, 128649, 58, 12, 36),
(1849, 'Initiate and conduct stakeholders meetings/assemblies', 'To promote participatory/informed decision-making', 'Increased stakeholders engagement', 'Meetings/assemblies, FGDs, open forums', 'Quarterly', 'School Head, Teachers, PTA ', '500', 'Ensure 80%-100%  participation of stakeholders', 2026, 129133, 59, 12, 151),
(1850, 'The school conducts needs-based LAC and learning and development activities', 'To strengthen the regular implementation of Learning Action Cell (LAC) sessions and Learning and Development (L&D) activities that enhance teachers’ professional competencies and improve instructional practices.', 'Regularly conducted and well-documented Learning Action Cell (LAC) sessions and Learning and Development (L&D) activities, with active teacher participation, approved schedules and session plans, and evidence of improved teaching practices, resulting in enhanced teacher competencies and better learner outcomes.', 'The school will conduct a training needs assessment to identify teachers’ professional development gaps and priority learning areas. Based on the results, a structured annual plan for Learning Action Cell (LAC) sessions and Learning and Development (L&D) activities will be prepared and integrated into the school calendar. Qualified facilitators, including master teachers and external resource persons, will be engaged to lead sessions focusing on instructional strategies, curriculum implementation, and assessment practices. Regular LAC meetings will be scheduled and implemented in a collaborative manner, ensuring active participation, sharing of best practices, and reflection among teachers. All activities will be properly documented, and monitoring and evaluation mechanisms will be established to assess effectiveness and guide continuous improvement of teaching and learning practices.', 'School Year 2026 - 2027', 'School Head, Master Teacher, Teachers ', '', '', 2026, 128941, 59, 12, 144),
(1851, 'Capacity Building for Teachers and Staff', 'To enhance competencies in SBM practices', 'Trained teachers and staff', 'LAC sessions, workshops', 'June, Aug, Dec 2026 and March 2027', 'School Head, SBM Coordinator', '6000', '', 2026, 128673, 58, 12, 0),
(1852, 'TEMPORARY ICT CLASSROOM SETUP', 'PROVIDE A SPACE FOR ICT ACTIVITIES', 'FUNCTIONAL TEMPORARY ICT LEARNING AREA', 'CONVERT CLASSROOM USING EXTENSION CORD,PORTABLE WIFI,SHARED LAPTOPS', 'WHOLE YEAR ROUND', 'SCHOOL HEAD-TEACHERS', '150000', 'ENSURE SAFETY MEASURES', 2026, 128828, 59, 12, 138),
(1853, 'Conduct an information drive\r\n', 'Increase awareness on school programs and services.', 'Informed stakeholders; increased participation.\r\n', 'Orientation sessions, IEC materials, PTA meetings.', 'April 2026 - June 2026', 'John Holden I. Medina ', '1500', '', 2026, 128628, 58, 12, 43),
