INSERT INTO `sgod_action_plan` (`id`, `activity`, `objective`, `ex_output`, `metho_strategy`, `time_frame`, `person_involved`, `bud_req`, `remarks`, `fy`, `school_id`, `division`, `region`, `district`) VALUES
(4211, 'Organize a School‑Based ALS Learning Program', 'Provide basic literacy and numeracy for out‑of‑school youth and adult learners in the Sitio Paraiso.', '1) At least one ALS learning session per week; 2) List of enrolled ALS learners with pre‑assessment records; 3) At least five (5) ALS completion certificate issued per year.', '1) Identify prospective ALS learners through barangay visitation and PTA 2) Coordinate with ALS Division Focal Person to assign a Learning Facilitator 3) Use available school space after class hours 4) Integrate simple livelihood inputs (e.g., basic gardening or crafts) to sustain interest.', 'SY 2026–2027 (ongoing)', 'chool Head, ALS Field Manager/Learning Facili', '5000', 'Need Division Approval', 2026, 137189, 107, 12, 68),
(4212, 'Assess and begin PWD‑friendly and inclusive‑education facilities upgrade', 'Make the school more accessible to children with special needs and PWDs.', '1.Simple assessment report of accessibility gaps (ramps, toilets, signage, classroom layout) 2) At least one PWD‑friendly toilet and one ramp installed within 1 school year 3) Consultants’ recommendations for future special‑education equipment.', '1) Conduct a barangay‑school accessibility audit with a municipal engineer or NGO partner 2) Prioritize low‑cost improvements (ramps, handrails, tactile markers) 3) Use MOOE or LGU funds for minor construction 4) Start a small “Special Education Advisory Group” of teachers and parents.', 'School Year 2026–2027 (ongoing)', 'School Head, Guidance Counselor, SGC Adviser,', '10000', 'Needs Project Proposal, include to PIA', 2026, 137189, 107, 12, 68),
(4213, 'Reactivating and sustaining SGC operations with regular activities', 'Ensure SGC is an active, representative, and functional student organization.', '1) At least one reorganizing SGC election held within SY2026 2) At least two SGC activities (e.g., flag ceremony leadership, clean-up drive, ALS support) per quarter 3) SGC constitution and activity logbook maintained.', '1) Conduct an orientation and election supervised by the SGC Adviser 2) Provide a simple SGC leadership‑training session 3) Include SGC in school planning meetings,crafting school policies 4) Encourage SGC to lead school‑based ALS learner‑support initiatives (peer tutoring, outreach).', 'School Year 2026–2027 (ongoing)', 'School Head, SGC Adviser, SGC Officers, Teach', '', '', 2026, 137189, 107, 12, 68),
(4214, 'Institutionalize teacher milestone‑achievement recognition program', 'Increase morale and motivation by formally recognizing long‑serving and exemplary teachers.', '1) At least one recognition ceremony per school year (e.g., “Teacher of the Year,” “Years of Service”) 2) Wall of Fame or teacher recognition board installed in the school 3) Simple written citations for each awardee.', '1) Set clear criteria (years of service, innovation, leadership, ALS/SGC involvement) 2) Form a small recognition committee (School Head, Parent, SPG rep. 3) Present awards during Teachers’ Month or school anniversary 4) Document achievements in the school logbook and website/FB page.', 'Annually (SY‑end celebration), with continuou', 'School Head, SGC Adviser, SGC Officers, Teach', '', '', 2026, 137189, 107, 12, 68),
(4215, 'Establish and operationalize a functional school library', 'Improve learners’ reading exposure and support ALS and regular pupils.', '1) At least one functional library space (even if shared) within SY2026-2027 2) Minimum of 100 usable books (storybooks, reference, ALS‑appropriate materials) within 1 year 3) At least one reading activity per week', '1) Identify a conducive room or corner 2) Solicit book donations from LGU, PTA, and retiring teachers 3) Assign a Librarian‑in‑Charge (teacher volunteer) and student library‑assistants 4) Use library materials to support ALS learners and remedial reading in Grades 1–3.', 'School Year 2026–2027 (ongoing)', 'School Head, SGC Adviser, SGC Officers, Teach', '', '', 2026, 137189, 107, 12, 68),
(4216, 'Assessment', 'To assess school PAPs and other good practices implemented within the school year', 'Assessed PAP\'s and other good practices implemented within the school year', 'Collect all data needed to assess PAP\'s and other school good practices using a tool/template', 'July 2026- December 2026', 'School Head, Teachers, SGC Members', '1000.00', 'Conduct assessment', 2026, 129179, 61, 12, 3),
(4217, 'SBM Evaluation', 'To conduct SBM evaluation regularly', 'Improved and sustained SBM and other school good practices', 'Present all necessary data during evaluation', 'March 2027', 'Principal, Teachers, and SGC Members', '5000', 'SBM evaluation', 2026, 129179, 61, 12, 3),
(4218, 'Stakeholders\' reorientation on SBM', 'To conduct stakeholders\' reorientation on SBM new policy and guidelines', '100% of Caganganan ES Teachers and stakeholders reoriented on the new SBM policy and guidelines', 'Conduct LAC session on DO #007 S. 2024', 'July 15, 2026', 'Principal, Teachers, SGC Members', '1000.00', 'The reorientation was conducted July 15, 2026, 1:30 PM at Principal\'s Office', 2026, 129179, 61, 12, 3),
(4219, 'SBM Implementation', 'To implement SBM on the new policy and guidelines', 'Implemented and improved SBM', 'Implement and conduct regular monitoring of SBM', 'July 2026- March 2027', 'Principal, Teachers and stakeholders', '3000', 'SBM Implementation', 2026, 129179, 61, 12, 3),
(4221, ' Monitoring and Evaluation of SBM Programs', 'To assess progress and effectiveness of implemented programs.', 'Updated progress reports and improved implementation.', 'Quarterly monitoring, meetings, accomplishment reports, feedback sessions', 'Quarterly', 'School Head, SBM Team, Teachers, Stakeholders', '1000', 'None', 2026, 128738, 106, 12, 133),
(4222, 'Observe what resources and facilities are available and make an inventory of its available learning resources', 'Identify and clarify resources that facilitate the teaching and learning process.', 'Inventory sheet of the school\'s availability of teaching and learning resources.', 'Assign a coordinator to monitor the inventory of the availability of learning resources.', 'August 2026', 'School head, LRMDS Coor. students', '', 'Observe what resources and facilities are available and make an inventory of them.', 2026, 304331, 61, 12, 3),
