INSERT INTO `sgod_action_plan` (`id`, `activity`, `objective`, `ex_output`, `metho_strategy`, `time_frame`, `person_involved`, `bud_req`, `remarks`, `fy`, `school_id`, `division`, `region`, `district`) VALUES
(6176, 'Project D.O.D.O (Dialogues, Outreach, Development, and Opportunities)', 'To strengthen school-based management through sustained dialogue, community outreach, inclusive development initiatives, and expanded learning opportunities for all learners. ', 'Strengthened school-based management with active stakeholder engagement, improved learner participation and performance, increased community support, and an inclusive, responsive, and continuously improving learning environment for all learners.', 'Implement participatory school-based management through regular stakeholder dialogues and planning sessions, community partnerships and outreach activities, data-driven decision-making using learner performance and Early Warning System data, and collaborative instructional strategies such as LAC sessions, remediation, and inclusive education practices.', 'Year-Round', 'School Head, SGC, PTA, All School Personnel, ', '4201000', '', 2026, 304202, 57, 12, 119),
(6178, 'Conduct of needs Assessment and School  Improvement Planning ( SIP )', 'To identify school needs and priorities for effective SBM Implementation', 'Completed needs assessment report updated School Improvement Plan (SIP)\r\nPrioritized Programs/ projects', 'Survey and Data gathering\r\nFocus Group Discussion\r\nSWOT Analysis and planning workshop', 'June 2026', 'School Head, Planning Team, MT, teachers, PTA', '500.00', '', 2026, 128469, 57, 12, 119),
(6179, 'Priority 2: Student Motivation & Family Socio-Economic Gaps (Item 3)', 'To mitigate the impact of poverty on student attendance and engagement through targeted community and school support systems.', 'Established school-community partnerships for student welfare (e.g., feeding programs, school supply drives).\r\n\r\nReduced chronic absenteeism among vulnerable learners.', 'Adopt-a-Student Program: Partner with local alumni, business owners, or NGOs to sponsor basic needs (fares, meals, school supplies) for high-risk students.\r\n\r\nFlexible Learning Options (FLOs): Provide contextualized, self-paced learning modules for students who must assist their families with livelihoods.', 'Year-Round / Progressive Implementation', 'School Head, Guidance Advocate, Class Advisor', '4000', 'monitored based on actual needs', 2026, 128308, 57, 12, 116),
(6180, 'Monitoring, Evaluation, and Stakeholders\' feedbacks mechanism', 'To monitor progress and evaluate the effectiveness of SBM implementation activities', 'Monitoring and evaluation reports\r\nStakeholders\' feedback records\r\nrecommendations for improvement', 'Regular monitoring visits\r\nMeetings and feedback sessions\r\nUse evaluation tools/ checklists', 'Monthly/ quarterly', 'School Head, SBM Committee, MT, Teachers, Par', '1000.00', '', 2026, 128469, 57, 12, 119),
(6181, 'Priority 3: On-Site Guidance & Counseling Infrastructure (Item 4)', 'To provide professional mental health, emotional, and specialized case management support for students ', 'A functional, designated guidance referral system.\r\n\r\nCapacity-building certificates for designated Guidance Advocates/Teachers.', 'Assigned teacher serves as guidance counselor ', 'Whole year round/ Progressive implementation', 'School Head, Guidance Advocate, Class Advisor', '1000.00', 'Success will be indicated by a fully established and clear referral workflow posted in the faculty room, along with documented case intake logs.', 2026, 128308, 57, 12, 116),
(6182, 'Priority 4: Community Stakeholder Attendance & Scheduling (Item 20)', 'To maximize stakeholder contribution and attendance in school-community planning sessions despite conflicting work schedules.', 'Increased stakeholder representation in school planning (PTA, Barangay Council) via hybrid channels.\r\n\r\nSigned and approved School Improvement Plan (SIP) / Annual Implementation Plan (AIP) with complete stakeholder inputs.', 'Asynchronous & Hybrid Collaboration: Utilize digital group chats, video conferencing, or physical feedback drops for stakeholders who cannot attend in-person meetings.', 'Whole year round/ Progressive implementation', 'School Head, Guidance Advocate, Class Advisor', '2000', 'Monitored through minutes of meetings, attendance sheets (both physical and screenshots of virtual attendees), and signed endorsement pages.', 2026, 128308, 57, 12, 116),
(6184, 'School Improvement Planning', 'To assess and update the SIP based on current school needs', 'updated SIP document', 'conduct meetings, data analysis, stakeholder consultation', 'July- August 2025', 'School Head, Teachers, PTA, Stakeholder', '5000', '', 2026, 128880, 60, 12, 31),
(6185, 'Conduct HPTA/ General PTA Assembly', 'To strengthen relationship among stakeholders and their continuous support / engagement', 'No. of HPTA/ General PTA Assembly Conducted', 'Regular stakeholders engagement activities, recognize stakeholders contributions and continuous collaboration and monitoring', 'Annually', 'SH, AO, BAC Chairman, BAC Members and Student', '3633', '', 2026, 128283, 57, 12, 116),
(6186, 'Priority 1: Remediation Constraints & Teacher Workload (Item 2)', 'To optimize teacher scheduling and boost learner participation in remedial classes without causing teacher burnout.', 'A consolidated, localized remediation schedule (e.g., dedicated \"Remediation Fridays\" or modular/asynchronous remediation blocks).\r\n\r\nAn increase in remedial class attendance by at least 20%.', 'Strategic Rescheduling: Implement peer-tutoring or cross-level teaching adjustments to free up specialized teachers.\r\n\r\nGamified/Incentivized Remediation: Integrate interactive, gamified learning materials to make remediation attractive to struggling learners.', 'Whole year round/ Progressive implementation', 'School Head, Guidance Advocate, Class Advisor', '4000', 'Monitored assessment result in CRLA', 2026, 128308, 57, 12, 116),
(6187, 'Workshop on Test Item Analysis', 'To familiarize teachers with the concepts, importance, and process of test item analysis', 'Teachers demonstrate understanding of item difficulty, discrimination index, and distractor efficiency; Improved teacher-made test items aligned with learning competencies', 'Hands-on workshop, peer coaching, group activity, and critiquing sessions', 'September 2026', 'School Head, Master Teachers', '3800', 'All teachers participate the workshop on Test Item Analysis', 2026, 304187, 57, 12, 124),
(6188, 'Construction/Improvement of PWD-Friendly Facilities', 'To provide accessible facilities that accommodate the needs of learners with disabilities', 'nstallation/improvement of ramps, handrails, comfort rooms, and signage for PWDs', 'Project implementation, coordination with LGU/PTA/community partners, resource mobilization, and other external stakeholders ', 'June-December 2026', 'School Head, Physical Facilities In-charge, S', '1000000', 'Subject to availability of funds and support', 2026, 304187, 57, 12, 124),
(6189, 'Brigada Eskwela Participation', 'To prepare school facilities before opening the classes', 'Clean and Safe school environment', 'volunteer work, donation drives', 'May-June 2025', 'School Head, Teachers, Parents, Community', '2000', 'Accomplished', 2026, 128880, 60, 12, 31),
